from hashlib import sha384
from pathlib import Path
import sys

root = Path(__file__).resolve().parents[1]
api = root / "backend/api"
target = root / "supabase/schema.sql"
parts = ["""-- Fresh Supabase project only. Run this entire file once in SQL Editor.
-- Generated by scripts/build_cloud_schema.py from the same SQL Render deploys.
BEGIN;
SELECT pg_advisory_xact_lock(718104521);
DO $$ BEGIN
    IF to_regclass('public.restaurants') IS NOT NULL OR to_regclass('public._sqlx_migrations') IS NOT NULL THEN
        RAISE EXCEPTION 'Existing installation detected. Use the Render migrator to upgrade.';
    END IF;
END $$;
""", (api / "src/cloud_base.sql").read_text(encoding="utf-8"), """
CREATE TABLE public._sqlx_migrations (
    version bigint PRIMARY KEY, description text NOT NULL,
    installed_on timestamptz NOT NULL DEFAULT now(), success boolean NOT NULL,
    checksum bytea NOT NULL, execution_time bigint NOT NULL
);
"""]
for path in sorted((api / "migrations_cloud").glob("*.sql")):
    version, name = path.stem.split("_", 1)
    sql = path.read_text(encoding="utf-8")
    digest = sha384(sql.encode()).hexdigest()
    description = name.replace("_", " ").replace("'", "''")
    parts.extend([f"-- {path.name}", sql,
                  f"INSERT INTO public._sqlx_migrations (version, description, success, checksum, execution_time) "
                  f"VALUES ({int(version)}, '{description}', true, decode('{digest}', 'hex'), 0);"])
parts.append("COMMIT;")
snapshot = "\n\n".join(p.rstrip() for p in parts) + "\n"
if "--check" in sys.argv:
    if target.read_text(encoding="utf-8") != snapshot:
        sys.exit("Regenerate supabase/schema.sql with scripts/build_cloud_schema.py")
else:
    target.write_bytes(snapshot.encode())
